#include "consolepresentation.h"

namespace ConsolePresentation {
QString MenuStyleSheet() {return QStringLiteral(
    "QMenu { background:white; color:#213547; border:1px solid #d9e2e8; padding:4px; }"
    "QMenu::item { padding:7px 28px 7px 12px; } QMenu::item:selected { background:#e8f5ef; }"
    "QMenu::item:disabled { color:#8a949e; background:transparent; }");}
QString OfflineToolStyleSheet() {return QStringLiteral(
    "QWidget#OfflineDataToolsWindow { background:#f4f7f9; color:#213547; }"
    "QWidget { font-size:13px; }"
    "QPushButton { min-height:26px; padding:3px 10px; }"
    "QComboBox, QLineEdit, QSpinBox { min-height:26px; }"
    "QWidget:disabled { color:#8a949e; }"
    "QComboBox QAbstractItemView::item:disabled { color:#8a949e; }");}
QString StyleSheet() {return QStringLiteral(
    "QMainWindow#MainWindow, QWidget#centralwidget { background:#f4f7f9; color:#213547; }"
    "#centralwidget, #centralwidget QWidget { font-size:13px; }"
    "#centralwidget QLabel, #centralwidget QCheckBox { color:#213547; background:transparent; }"
    "#centralwidget QCheckBox::indicator { width:14px; height:14px; border:1px solid #a7b9c6; border-radius:2px; background:white; }"
    "#centralwidget QCheckBox::indicator:checked { background:#087f5b; border-color:#087f5b; image:url(:/console/check.xpm); }"
    "#centralwidget QCheckBox::indicator:disabled { border-color:#c3ced5; background:#edf1f4; }"
    "#centralwidget QCheckBox::indicator:checked:disabled { background:#8b9da8; image:url(:/console/check.xpm); }"
    "#centralwidget QFrame#HeaderPanel { background:transparent; border:0; }"
    "#centralwidget QLabel#Title { font-size:22px; font-weight:700; color:#153249; }"
    "#centralwidget QLabel#SetupPanelTitle, #centralwidget QLabel#RunPanelTitle, #centralwidget QLabel#FieldsTitle,"
    "#centralwidget QLabel#StatusSectionTitle, #centralwidget QLabel#LogTitle { font-size:15px; font-weight:700; color:#153249; }"
    "#centralwidget QFrame#SetupPanel, #centralwidget QFrame#RunPanel, #centralwidget QWidget#FieldsPanel,"
    "#centralwidget QWidget#StatusPanel, #centralwidget QWidget#PlotPanel, #centralwidget QWidget#LogPanel { background:white; border:1px solid #d9e2e8; border-radius:4px; }"
    "#centralwidget QToolButton { background:transparent; border:0; color:#213d51; padding:4px 8px; }"
    "#centralwidget QToolButton:hover { background:#e8f5ef; border-radius:4px; }"
    "#centralwidget QPushButton { background:#f8fafb; color:#244354; border:1px solid #d0dde5; border-radius:4px; padding:5px 10px; min-height:20px; font-weight:600; }"
    "#centralwidget QPushButton:hover { background:#edf6f2; border-color:#94bfae; }"
    "#centralwidget QPushButton:pressed { background:#dcefe6; }"
    "#centralwidget QWidget#FieldsPanel QPushButton { font-size:12px; padding:4px 6px; font-weight:500; }"
    "#centralwidget QPushButton#StartRun { background:#087f5b; border-color:#087f5b; color:white; font-weight:700; }"
    "#centralwidget QPushButton#StartRun:hover { background:#066b4c; }"
    "#centralwidget QPushButton#StopRun, #centralwidget QPushButton#Disconnect, #centralwidget QPushButton#Regress { background:#fff8f8; color:#b53840; border-color:#e4afb3; }"
    "#centralwidget QPushButton#Progress { background:#eff8f3; color:#087f5b; border-color:#add8c5; }"
    "#centralwidget QPushButton:disabled { background:#edf1f4; color:#718394; border-color:#e1e7ec; }"
    "#centralwidget QPushButton#StartRun:disabled, #centralwidget QPushButton#StopRun:disabled, #centralwidget QPushButton#Disconnect:disabled,"
    "#centralwidget QPushButton#Regress:disabled, #centralwidget QPushButton#Progress:disabled { background:#edf1f4; color:#718394; border-color:#e1e7ec; }"
    "#centralwidget QLineEdit, #centralwidget QSpinBox, #centralwidget QComboBox, #centralwidget QPlainTextEdit { background:white; border:1px solid #ccdbe5; border-radius:3px; padding:4px 8px; color:#213547; selection-background-color:#ddf3ea; selection-color:#173f33; }"
    "#centralwidget QLineEdit:focus, #centralwidget QSpinBox:focus, #centralwidget QComboBox:focus { border-color:#399c80; }"
    "#centralwidget QLineEdit:disabled, #centralwidget QSpinBox:disabled { color:#718394; background:#f5f7f9; }"
    "#centralwidget QSpinBox { padding-right:24px; font-size:14px; font-weight:600; }"
    "#centralwidget QSpinBox QLineEdit { border:0; padding:0; background:transparent; font-size:14px; font-weight:600; }"
    "#centralwidget QSpinBox::up-button, #centralwidget QSpinBox::down-button { width:22px; background:#eff4f7; border-left:1px solid #dce5eb; }"
    "#centralwidget QSpinBox::up-button { subcontrol-origin:border; subcontrol-position:top right; border-bottom:1px solid #dce5eb; border-top-right-radius:3px; }"
    "#centralwidget QSpinBox::down-button { subcontrol-origin:border; subcontrol-position:bottom right; border-bottom-right-radius:3px; }"
    "#centralwidget QSpinBox::up-button:hover, #centralwidget QSpinBox::down-button:hover { background:#ddf3ea; }"
    "#centralwidget QSpinBox::up-arrow { image:url(:/console/up.xpm); width:12px; height:8px; }"
    "#centralwidget QSpinBox::down-arrow, #centralwidget QComboBox::down-arrow { image:url(:/console/down.xpm); width:12px; height:8px; }"
    "#centralwidget QDoubleSpinBox { background:white; color:#213547; border:1px solid #ccdbe5; border-radius:3px; padding:2px 24px 2px 6px; }"
    "#centralwidget QDoubleSpinBox QLineEdit { border:0; padding:0; background:transparent; }"
    "#centralwidget QDoubleSpinBox::up-button, #centralwidget QDoubleSpinBox::down-button { width:20px; border-left:1px solid #dce5eb; background:#eff4f7; }"
    "#centralwidget QDoubleSpinBox::up-button { subcontrol-origin:border; subcontrol-position:top right; border-bottom:1px solid #dce5eb; }"
    "#centralwidget QDoubleSpinBox::down-button { subcontrol-origin:border; subcontrol-position:bottom right; }"
    "#centralwidget QDoubleSpinBox::up-arrow { image:url(:/console/up.xpm); width:12px; height:8px; }"
    "#centralwidget QDoubleSpinBox::down-arrow { image:url(:/console/down.xpm); width:12px; height:8px; }"
    "#centralwidget QDoubleSpinBox:disabled { background:#f5f7f9; color:#718394; }"
    "#centralwidget QLabel#AutoRunTitle { font-size:13px; font-weight:600; }"
    "#centralwidget QLabel#AutoRunStatus { color:#718394; font-size:11px; }"
    "#centralwidget QWidget#AutoRunControls QPushButton { font-size:12px; padding:2px 6px; }"
    "#centralwidget QWidget#AutoRunControls QSpinBox, #centralwidget QWidget#AutoRunControls QSpinBox QLineEdit { font-size:12px; font-weight:400; }"
    "#centralwidget QComboBox { padding-right:24px; }"
    "#centralwidget QComboBox::drop-down { width:22px; border:0; border-left:1px solid #dce5eb; }"
    "#centralwidget QComboBox QAbstractItemView { background:white; color:#213547; selection-background-color:#ddf3ea; selection-color:#163e32; }"
    "#centralwidget QTableWidget { font-size:12px; background:white; alternate-background-color:#f8fafc; color:#244354; border:1px solid #d7e3eb; border-radius:3px; gridline-color:#e3eaf0; selection-background-color:#ddf3ea; selection-color:#163e32; }"
    "#centralwidget QPlainTextEdit#Log { font-family:monospace; font-size:12px; padding:6px 8px; border-radius:3px; }"
    "#centralwidget QTableWidget::item { padding:0px 5px; }"
    "#centralwidget QTableWidget::item:selected { background:#ddf3ea; color:#163e32; }"
    "#centralwidget QHeaderView::section { background:#eff4f7; color:#29485d; font-weight:600; padding:3px 5px; border:0; border-right:1px solid #dce5eb; border-bottom:1px solid #dce5eb; }"
    "#centralwidget QLabel#Mode, #centralwidget QFrame#ConnectionStatusBadge { background:#e8f5ef; border:1px solid #b8dccc; border-radius:4px; color:#07583e; padding:4px 8px; font-weight:600; }"
    "#centralwidget QFrame#ConnectionStatusBadge { padding:0; background:#eff3f6; border-color:#d4dfe6; }"
    "#centralwidget QFrame#ConnectionStatusBadge[state='running'], #centralwidget QFrame#ConnectionStatusBadge[connected='true'] { background:#e8f5ef; border-color:#b8dccc; }"
    "#centralwidget QFrame#ConnectionStatusBadge[state='busy'] { background:#fff4df; border-color:#e5ca96; }"
    "#centralwidget QFrame#ConnectionStatusBadge[state='error'] { background:#fff0f1; border-color:#e5b6bb; }"
    "#centralwidget QLabel#Phase { font-weight:600; padding:0; }"
    "#centralwidget QLabel#Elapsed, #centralwidget QLabel#ConfigPath, #centralwidget QLabel#OrderNote { color:#718394; }"
    "#centralwidget QLabel[summary='true'] { background:#f6f9fb; border:1px solid #dce5eb; border-radius:4px; padding:5px 9px; }"
    "#centralwidget QLabel[summary='true'][health='fault'] { color:#ad303b; border-color:#e7b8bc; background:#fff4f4; }"
    "#centralwidget QScrollBar:vertical { background:#f3f6f8; width:10px; margin:0; }"
    "#centralwidget QScrollBar:horizontal { background:#f3f6f8; height:10px; margin:0; }"
    "#centralwidget QScrollBar::handle { background:#bacbd5; border-radius:4px; min-height:20px; min-width:20px; }"
    "#centralwidget QCheckBox:disabled, #centralwidget QToolButton:disabled, #centralwidget QComboBox:disabled,"
    "#centralwidget QComboBox QAbstractItemView::item:disabled { color:#8a949e; }"
    "#centralwidget QScrollBar::add-line, #centralwidget QScrollBar::sub-line { width:0; height:0; }"
    "#centralwidget QSplitter::handle { background:#f4f7f9; }"
    "QStatusBar { background:#f4f7f9; color:#718394; border:0; }");}}
